#!/usr/bin/env python3
"""Compute ground truth for CSX-037_Q2 from local CSX-037 event data."""

from __future__ import annotations

import json
import re
from html import unescape
from pathlib import Path


TASK_ID = "CSX-037_Q2"
EVENT_ID = "CSX-037"
DIAGNOSTIC_COLD_THRESHOLD_C = 10.0
SEVERE_COLD_THRESHOLD_C = 5.0
FREEZING_THRESHOLD_C = 0.0


def package_dir() -> Path:
    repo_root = Path(__file__).resolve().parents[3]
    return repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(relative_path: str) -> dict:
    with (package_dir() / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_text(relative_path: str) -> str:
    data = (package_dir() / relative_path).read_bytes()
    for encoding in ("utf-8", "utf-8-sig", "latin-1"):
        try:
            return data.decode(encoding)
        except UnicodeDecodeError:
            continue
    return data.decode("utf-8", errors="replace")


def strip_html(value: str) -> str:
    value = re.sub(r"(?is)<script.*?</script>", " ", value)
    value = re.sub(r"(?is)<style.*?</style>", " ", value)
    text = re.sub(r"(?s)<[^>]+>", " ", value)
    return re.sub(r"\s+", " ", unescape(text)).strip()


def longest_run(flags: list[bool]) -> int:
    best = current = 0
    for flag in flags:
        if flag:
            current += 1
            best = max(best, current)
        else:
            current = 0
    return best


def wind_chill_c(temp_c: float, wind_kmh: float) -> float:
    if temp_c > 10.0 or wind_kmh <= 4.8:
        return temp_c
    wind_factor = wind_kmh**0.16
    return 13.12 + 0.6215 * temp_c - 11.37 * wind_factor + 0.3965 * temp_c * wind_factor


def compute_weather_metrics() -> dict:
    source_path = "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive_cold_variables.json"
    weather = read_json(source_path)
    hourly = weather["hourly"]
    temps = [float(value) for value in hourly["temperature_2m"]]
    winds = [float(value) for value in hourly["wind_speed_10m"]]
    wind_chills = [wind_chill_c(temp, wind) for temp, wind in zip(temps, winds)]

    le5_flags = [temp <= SEVERE_COLD_THRESHOLD_C for temp in temps]
    lowland_freezing_flags = [temp <= FREEZING_THRESHOLD_C for temp in temps]
    wind_chill_freezing_flags = [value <= FREEZING_THRESHOLD_C for value in wind_chills]

    return {
        "source_path": source_path,
        "hour_count": len(temps),
        "min_temperature_c": round(min(temps), 1),
        "min_temp_threshold_anomaly_c": round(min(temps) - DIAGNOSTIC_COLD_THRESHOLD_C, 1),
        "severe_cold_duration_hours_le_5c": int(sum(le5_flags)),
        "longest_run_temperature_le_5c_hours": int(longest_run(le5_flags)),
        "lowland_freezing_hours": int(sum(lowland_freezing_flags)),
        "lowland_freezing_load_c_hours": round(
            sum(max(FREEZING_THRESHOLD_C - temp, 0.0) for temp in temps),
            1,
        ),
        "min_wind_chill_c": round(min(wind_chills), 1),
        "hours_wind_chill_le_0c": int(sum(wind_chill_freezing_flags)),
        "wind_chill_freezing_load_c_hours": round(
            sum(max(FREEZING_THRESHOLD_C - value, 0.0) for value in wind_chills),
            1,
        ),
    }


def compute_report_flags() -> dict:
    source_path = "data/event_reports/event_reports_001_Locked_package_evidence_report.bin"
    report_text = strip_html(read_text(source_path))
    lowered = report_text.lower()
    observatory_low_match = re.search(
        r"lowest temperature recorded at the Observatory.*?was\s+([0-9.]+)\s+degrees",
        report_text,
        flags=re.I,
    )
    return {
        "source_path": source_path,
        "hko_observatory_low_c": round(float(observatory_low_match.group(1)), 1)
        if observatory_low_match
        else None,
        "freezing_rain_flag": "freezing rain" in lowered,
        "icing_flag": "icing" in lowered,
        "slippery_or_icy_road_flag": "slippery road" in lowered or "icy road" in lowered,
    }


def scoring_rubric() -> dict:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "JSON response shape",
                "points": 4,
                "description": "Returns compact JSON with the five requested numeric fields and one concise interpretation sentence.",
                "partial_credit": "Award 2-3 points for readable JSON with one missing numeric field or a verbose but still relevant interpretation; award at most 1 point if the response is not machine-readable.",
            },
            {
                "name": "Air-temperature freezing ledger",
                "points": 4,
                "description": "Computes lowland freezing load as 0.0 C-hours and does not imply a lowland subzero air-temperature interval.",
                "partial_credit": "Award 2 points for recognizing no lowland air-temperature freezing even if the C-hour formula is omitted; award 1 point for using the right formula with a minor threshold or rounding error.",
            },
            {
                "name": "Cold-threshold ledger",
                "points": 4,
                "description": "Computes the minimum-temperature anomaly as about -5.7 C relative to 10 C and the duration at or below 5 C as 14 hours.",
                "partial_credit": "Award 2 points for either the correct anomaly or the correct duration; award 3 points if both are conceptually correct but one is slightly outside tolerance.",
            },
            {
                "name": "Wind-chill ledger",
                "points": 4,
                "description": "Computes wind-chill freezing load near 4.1 C-hours from the hourly temperature and wind-speed series.",
                "partial_credit": "Award 2-3 points for applying wind chill and identifying subzero wind-chill exposure with a small arithmetic or rounding error; award at most 1 point for treating wind chill as air temperature.",
            },
            {
                "name": "Report-coded ice score",
                "points": 2,
                "description": "Scores freezing-rain, icing, and slippery/icy-road text flags as 1 + 1 + 1 = 3.",
                "partial_credit": "Award 1 point for finding two of the three report-coded high-ground ice indicators or for the right total with unclear flag accounting.",
            },
            {
                "name": "Computed interpretation",
                "points": 2,
                "description": "Keeps the interpretation tied to the computed fingerprint rather than adding loss estimates, broad event narrative, or guidance.",
                "partial_credit": "Award 1 point for a mostly correct but over-broad interpretation; award no credit for guidance, loss claims, or a generic cold-wave summary not tied to the computed fields.",
            },
        ],
    }


def build_ground_truth() -> dict:
    weather = compute_weather_metrics()
    report = compute_report_flags()
    ice_score = int(report["freezing_rain_flag"]) + int(report["icing_flag"]) + int(report["slippery_or_icy_road_flag"])

    numeric_ledger = {
        "lowland_freezing_load_c_hours": weather["lowland_freezing_load_c_hours"],
        "min_temp_threshold_anomaly_c": weather["min_temp_threshold_anomaly_c"],
        "severe_cold_duration_hours_le_5c": weather["severe_cold_duration_hours_le_5c"],
        "wind_chill_freezing_load_c_hours": weather["wind_chill_freezing_load_c_hours"],
        "high_ground_ice_report_score_0to3": ice_score,
    }

    interpretation = (
        "Lowland air temperature stayed above 0 C, while wind chill produced a small subzero load "
        "and the report text contains all three high-ground ice signals."
    )
    primary_gt = {
        "answer": numeric_ledger,
        "interpretation": interpretation,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "eval_mode": "deterministic",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "target_family": "cold_process_fingerprint",
        "primary_gt": primary_gt,
        "numeric_tolerances": {
            "lowland_freezing_load_c_hours": {"value": 0.0, "tolerance": 0.1},
            "min_temp_threshold_anomaly_c": {"value": -5.7, "tolerance": 0.2},
            "severe_cold_duration_hours_le_5c": {"value": 14, "tolerance": 0},
            "wind_chill_freezing_load_c_hours": {"value": 4.1, "tolerance": 0.2},
            "high_ground_ice_report_score_0to3": {"value": 3, "tolerance": 0},
        },
        "key_values": {
            "interpretation": interpretation,
            "min_temperature_c": weather["min_temperature_c"],
            "lowland_freezing_hours": weather["lowland_freezing_hours"],
            "longest_run_temperature_le_5c_hours": weather["longest_run_temperature_le_5c_hours"],
            "min_wind_chill_c": weather["min_wind_chill_c"],
            "hours_wind_chill_le_0c": weather["hours_wind_chill_le_0c"],
            "hko_observatory_low_c": report["hko_observatory_low_c"],
            "report_flags": {
                "freezing_rain_flag": report["freezing_rain_flag"],
                "icing_flag": report["icing_flag"],
                "slippery_or_icy_road_flag": report["slippery_or_icy_road_flag"],
            },
        },
        "rubric": scoring_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [weather["source_path"], report["source_path"]],
        },
    }


def main() -> None:
    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    with output_path.open("w", encoding="utf-8") as handle:
        json.dump(build_ground_truth(), handle, indent=2, sort_keys=True)
        handle.write("\n")


if __name__ == "__main__":
    main()
